    "lede": "تنتقلون من كونمينغ إلى المنازل التاريخية والأزقة في جيانشوي ثم إلى مدرجات أرز يوانيانغ. تتيح ليلتان هناك فرصًا متعددة لاستكشاف المناظر وقرى شعب هاني. يبقى شروق الشمس والانعكاسات وبحر السحاب رهنًا بالطقس.",
    "summary": "خمس ليالٍ مع الإفطار: كونمينغ 2، وجيانشوي 1، ويوانيانغ 2. مرشد وسيارة خاصان من اليوم 2 إلى اليوم 5.",
