    "hotelNote": "خمس ليالٍ مع الإفطار على أساس إقامة شخصين في الغرفة: كونمينغ 2، وجيانشوي 1، ويوانيانغ 2. في يوانيانغ، يُؤكد موقع الغرفة والسلالم والتدفئة أو التكييف والإطلالة قبل الدفع.",
    "serviceNote": "تشمل الأيام من 2 إلى 5 مرشدًا خاصًا يتحدث الإنجليزية وسائقًا وسيارة ورسوم دخول المعالم الرئيسية المقررة والحافلات المحلية الداخلية الإلزامية. تتضمن النسخة الكورية مرشدًا يتحدث الكورية بالسعر الأساسي نفسه، رهن التوافر.",
    "bookingNote": "المبالغ المعروضة أسعار ابتدائية للفرد بحسب عدد المشاركين المحدد ونطاق الخدمات الموصوف. أرسلوا مواعيد السفر وتوزيع الغرف وتفاصيل الوصول وعدد قطع الأمتعة. تُؤكد الفنادق والتنقلات ولغات الإرشاد وأي رسوم موسمية والسعر الإجمالي كتابيًا قبل الدفع.",
