    "hotelNote": "من أصل ست عشرة ليلة، تقضون ثلاث عشرة في فنادق بمستوى أربع نجوم مع الإفطار (4 ماسات على Trip.com/Ctrip): بكين 4، وشيآن 2، وتشنغدو 2، وتشونغتشينغ 1، وشنغهاي 4. تُقضى ثلاث ليالٍ في مقصورة عادية بشرفة على سفينة يانغتسي مصنفة خمس نجوم، عادةً من Gold Cruises. قد تكون الشرفة مغلقة بالزجاج في أدنى طابق للمقصورات؛ ويستلزم الطابق الأعلى رسومًا إضافية. الإقامة لشخصين؛ وتُؤكد السفينة والطابق والمقصورة لموعد الإبحار.",
    "serviceNote": "في أيام الجولات البرية، تعمل لمجموعتكم سيارة ومرشد محلي خاص يتحدث الإنجليزية. تشمل الرحلة النقل ورسوم الدخول الرئيسية المقررة وقطارات الدرجة الثانية على مسار بكين–شيآن–تشنغدو–تشونغتشينغ ورحلة شنغهاي–سوتشو ذهابًا وإيابًا، إضافةً إلى قطار أو طيران اقتصادي ييتشانغ–شنغهاي. تشمل الليالي الثلاث على متن السفينة المقصورة والوجبات من عشاء الصعود حتى الإفطار الأخير وثلاث رحلات، عادةً فنغدو والمضائق الثلاثة الصغيرة بقارب أصغر وسد المضائق الثلاثة. يُقدم الشرح باللغات التي توفرها السفينة. يتغير المرشد البري بحسب المدينة؛ ويتوفر سائق في طرفي رحلات القطار والطيران. يمكن توفير مرشدين بالكورية بالسعر نفسه رهن التوافر.",
    "bookingNote": "السعر الابتدائي للفرد بحسب عدد المشاركين المحدد وعلى أساس إقامة شخصين في الغرفة والمقصورة العادية ذات الشرفة. تُؤكد السفينة والمقصورة وأي رسوم موسم ذروة والسعر الإجمالي كتابيًا قبل الدفع. تلزم بيانات جوازات السفر قبل فتح حجوزات المدينة المحرمة وجيش التيراكوتا.",
