    "hotelNote": "يفترض السعر المعروض إقامة شخصين في الغرفة والمقصورة. تبدأ رسوم الاستخدام الفردي للغرفة والمقصورة طوال الرحلة من 1,090 USD. تقضون ثلاثًا من الليالي الست عشرة في مقصورة عادية بشرفة على سفينة خمس نجوم، عادةً من Gold Cruises. تُقضى الليالي الثلاث عشرة الأخرى في فنادق بمستوى أربع نجوم أو 4 ماسات على Trip.com/Ctrip مع الإفطار: بكين 4، وشنغهاي 4، وشيآن 2، وتشنغدو 2، وتشونغتشينغ 1. تُذكر أسماء الفنادق في التأكيد.",
