    "bookingNote": "السعر المعروض «ابتداءً من» للفرد في موعد انطلاق ثابت، على أساس إقامة شخصين في الغرفة. تُنفذ الرحلة بحد أدنى 8 مشاركين وبحد أقصى 12. إذا كان عدد المسجلين أقل من 8 قبل المغادرة بـ45 يومًا، نقدم كتابيًا رحلة خاصة بسعر يلائم عدد مجموعتكم. يمكنكم قبولها في المواعيد نفسها أو استرداد جميع المبالغ المدفوعة إلى Homeground. تستطيع المجموعات المشكلة مسبقًا من 8 إلى 12 شخصًا اختيار مواعيدها بسعر المجموعة الصغيرة؛ ويحتاج 13 شخصًا فأكثر إلى عرض منفصل. لم تُحجز المقصورات أو رحلة الإبحار بعد. نراجع التوافر ونحدد السفينة وفئة المقصورة كتابيًا ونؤكد السعر الإجمالي قبل الدفع. تصعد المجموعات المخططة إلى السفينة أيام الجمعة؛ وقد يتغير المسار أو المواعيد إذا اختلف جدول 2027. تحتاج المجموعة الخاصة المشكلة من 8 إلى 12 شخصًا أيضًا إلى إبحار من تشونغتشينغ في اليوم 10، ويُراجع ذلك أولًا. تكون مجموعة سبتمبر في شنغهاي خلال عيد منتصف الخريف في 15 سبتمبر 2027، حيث يزدحم البوند وحديقة يو أكثر. تُؤكد الفنادق والطيران والسعر الإجمالي كتابيًا قبل الدفع.",
