    "hotelNote": "أربع عشرة ليلة مع الإفطار على أساس إقامة شخصين في الغرفة: بكين 3، وشيآن 2، وتشانغيه 1، وجيايوغوان 1، ودونهوانغ 2، وتوربان 2، وأورومتشي 2، وليلة قرب مطار المغادرة. فنادق بمستوى أربع نجوم أو 4 ماسات على Trip.com/Ctrip حيث تتوفر هذه الفئة. في تشانغيه وجيايوغوان وتوربان، يُؤكد قبل الدفع مكان الإقامة المحلي الأنسب من بين المنشآت التي خضعت للتقييم.",
    "serviceNote": "يعمل المرشد المحلي والسيارة لمجموعتكم فقط في أيام الجولات؛ وتُراجع اللغة لكل مدينة. تشمل الرحلة جميع خدمات النقل ورسوم دخول المعالم الرئيسية المقررة، ومنها موغاو وقلعة جيايوغوان وحافلة البحيرة السماوية. تشمل قطارات الدرجة الثانية على مسارات بكين–شيآن–تشانغيه وليويوان الجنوبية–توربان وتوربان–أورومتشي، مع قطار أو سيارة خاصة لمساري تشانغيه–جيايوغوان وجيايوغوان–دونهوانغ. الرحلة الجوية الاقتصادية من أورومتشي إلى شرق الصين مشمولة. يتولى السائقون نقل محطات القطار والمطارات. احتفظوا بوثيقة هويتكم جاهزة للفحص في الفنادق والمحطات وبعض معالم شينجيانغ.",
    "bookingNote": "السعر الابتدائي للفرد بحسب عدد المشاركين المحدد وعلى أساس إقامة شخصين في الغرفة. تفرض موغاو عددًا محدودًا من التذاكر المؤرخة؛ وإذا لم تتوفر إلا التذكرة البديلة لأربعة كهوف، نبلغكم قبل الدفع. تلزم بيانات جوازات السفر قبل فتح حجوزات المدينة المحرمة وجيش التيراكوتا. تُؤكد القطارات والطيران والفنادق والسعر الإجمالي أيضًا كتابيًا قبل الدفع.",
